int main() {
    int m;
    cin >> m;
    cin.ignore();
    string input;
    getline(cin, input);
    vector<int> nums = split(input, ",");

    // 单调栈
    int n = nums.size();
    vector<int> res;
    vector<int> stk(n, 0);
    int start = 0;
    int end = 0;
​
    for (int i = 0; i < n; i++) {
​
        // 剔除超过范围数据
        while (end > start && stk[start] + m - 1 < i) {
            start++;
        }
​
        // 维持递增
        while (end > start && nums[stk[end - 1]] >= nums[i]) {
            end--;
        }
        stk[end++] = i;

        // 栈底的元素为最小值
        if (i >= m -1) {
            res.push_back(nums[stk[start]]);
        }
    }
​
​
    // 输出结果
    int len = res.size();
    for (int i = 0; i < len; i++) {
        cout << res[i];
        if (i != len - 1) {
            cout << ",";
        }
    }
    return 0;
}

