    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
​
        int m = Integer.parseInt(sc.nextLine()); // 读取窗口大小
        String[] parts = sc.nextLine().split(","); // 分割数字字符串
​
        int n = parts.length;
        int[] nums = new int[n];
        for (int i = 0; i < n; i++) nums[i] = Integer.parseInt(parts[i]);
​
        List<Integer> res = new ArrayList<>();
        Deque<Integer> deque = new ArrayDeque<>();
​
        for (int i = 0; i < n; i++) {
            // 移除超出窗口的元素
            while (!deque.isEmpty() && deque.peekFirst() + m - 1 < i) {
                deque.pollFirst();
            }
            // 维护单调递增栈
            while (!deque.isEmpty() && nums[deque.peekLast()] >= nums[i]) {
                deque.pollLast();
            }
            deque.addLast(i);
            // 当前窗口已满，添加栈底最小值
            if (i >= m - 1) {
                res.add(nums[deque.peekFirst()]);
            }
        }
​
        System.out.println(String.join(",", res.stream().map(String::valueOf).toArray(String[]::new)));
    }
}
